style.css:
/* Thay đổi nền trang web theo ý muốn */
body {
    background-image: url("https://your-image-link.com/image.jpg"); /* Thay bằng link ảnh của bạn */
    background-size: cover;  /* Phủ kín toàn bộ màn hình */
    background-attachment: fixed;  /* Giữ nguyên khi cuộn trang */
    background-position: center; /* Căn giữa hình nền */
}

/* Nếu muốn nền chỉ áp dụng cho một trang web cụ thể */
@-moz-document domain("example.com") {
/* Thay example.com bằng trang bạn muốn áp dụng */
    body {
        background-image: url("https://your-image-link.com/image.jpg");
    }
}
